package server

const layout = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="csrf-token" content="{{.CSRF}}"><title>snusnu</title><link href="/assets/bootstrap.min.css" rel="stylesheet"></head><body class="bg-primary-subtle"><nav class="navbar navbar-expand-xl navbar-dark bg-primary mb-4 shadow-sm"><div class="container-fluid px-3 px-lg-4"><a class="navbar-brand" href="/dashboard">snusnu</a><button class="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#mainNav" aria-controls="mainNav" aria-expanded="false" aria-label="Toggle navigation"><span class="navbar-toggler-icon"></span></button><div class="collapse navbar-collapse" id="mainNav">{{if .User}}<div class="navbar-nav me-auto"><a class="nav-link" href="/dashboard">My routers</a><a class="nav-link" href="/directory">Global directory</a><a class="nav-link" href="/llc-macs">LLC MACs</a><a class="nav-link" href="/flows">Flows</a><a class="nav-link" href="/clients">API clients</a>{{if eq .User.Role "admin"}}<div class="nav-item dropdown"><a class="nav-link dropdown-toggle" href="#" role="button" data-bs-toggle="dropdown" aria-expanded="false">Admin</a><div class="dropdown-menu"><a class="dropdown-item" href="/admin/routers">All routers</a><a class="dropdown-item" href="/admin/llc-macs">All MACs</a><a class="dropdown-item" href="/admin/users">Users</a><a class="dropdown-item" href="/admin/blocks">All blocks</a><a class="dropdown-item" href="/planning-directory">Planning</a><a class="dropdown-item" href="/connections">Planned connections</a></div></div>{{end}}</div><div class="dropdown ms-xl-3"><button class="btn btn-outline-light dropdown-toggle d-flex align-items-center gap-2" type="button" data-bs-toggle="dropdown" aria-expanded="false"><span class="rounded-circle bg-light text-primary d-inline-flex justify-content-center align-items-center" style="width:1.7rem;height:1.7rem" aria-hidden="true">&#9786;</span><span>{{if .User.Username}}{{.User.Username}}{{else}}{{.User.Email}}{{end}}</span></button><div class="dropdown-menu dropdown-menu-end p-2" style="min-width:14rem"><div class="small text-muted px-2 text-truncate">{{.User.Email}}</div><a class="dropdown-item" href="/profiles/{{.User.ID}}">Profile</a><a class="dropdown-item" href="/settings">Settings</a><a class="dropdown-item" href="/blocks">My blocklist</a><div class="dropdown-divider"></div><form method="post" action="/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="dropdown-item" type="submit">Sign out</button></form></div></div>{{else}}<div class="navbar-nav ms-auto"><a class="nav-link" href="/login">Sign in</a><a class="nav-link" href="/register">Register</a></div>{{end}}</div></div></nav><main class="container pb-5">{{template "content" .}}</main><script src="/assets/bootstrap.bundle.min.js"></script></body></html>`

var pages = map[string]string{
	"register":             `{{define "content"}}<div class="col-md-6 mx-auto"><h1>Create account</h1><form method="post" action="/register"><label class="form-label w-100">Email<input class="form-control" type="email" name="email" required maxlength="254"></label><label class="form-label w-100">SNA NETID (1–8 characters)<input class="form-control text-uppercase" name="netid" minlength="1" maxlength="8" pattern="[A-Za-z@#$][A-Za-z0-9@#$]{0,7}" required></label><div class="form-text mb-3">This globally unique NETID belongs to your user account and applies to all of your routers.</div><label class="form-label w-100">Password (12–72 characters)<input class="form-control" type="password" name="password" required minlength="12" maxlength="72"></label>{{if .CaptchaKey}}<div class="g-recaptcha my-3" data-sitekey="{{.CaptchaKey}}"></div><script src="https://www.google.com/recaptcha/api.js" async defer></script>{{end}}<div><button class="btn btn-primary mt-3">Register</button></div></form></div>{{end}}`,
	"verify":               `{{define "content"}}<div class="col-md-6 mx-auto"><h1>Verify email</h1><p>Enter the six-digit code sent to your email. It expires in 10 minutes.</p><form method="post" action="/verify"><label class="form-label">Email<input class="form-control" type="email" name="email" value="{{.Email}}" required></label><br><label class="form-label">Code<input class="form-control" name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></label><div><button class="btn btn-primary mt-3">Verify</button></div></form><form method="post" action="/verify/resend" class="mt-4"><input type="hidden" name="email" value="{{.Email}}">{{if .CaptchaKey}}<div class="g-recaptcha my-3" data-sitekey="{{.CaptchaKey}}"></div><script src="https://www.google.com/recaptcha/api.js" async defer></script>{{end}}<button class="btn btn-link p-0">Send another code</button></form></div>{{end}}`,
	"login":                `{{define "content"}}<div class="row justify-content-center"><div class="col-12 col-sm-10 col-md-7 col-lg-5"><div class="card border-0 shadow-sm"><div class="card-body p-4 p-md-5"><h1 class="h3 mb-4">Sign in</h1>{{if .Error}}<div class="alert alert-danger" role="alert">{{.Error}}</div>{{end}}<form method="post" action="/login"><div class="mb-3"><label class="form-label" for="login-email">Email address</label><input class="form-control" id="login-email" type="email" name="email" value="{{.Email}}" autocomplete="username" required></div><div class="mb-3"><label class="form-label" for="login-password">Password</label><input class="form-control" id="login-password" type="password" name="password" autocomplete="current-password" required></div><div class="form-check mb-4"><input class="form-check-input" id="remember" type="checkbox" name="remember" value="1" {{if .Remember}}checked{{end}}><label class="form-check-label" for="remember">Remember me for 30 days</label></div>{{if .CaptchaKey}}<div class="g-recaptcha mb-3" data-sitekey="{{.CaptchaKey}}"></div><script src="https://www.google.com/recaptcha/api.js" async defer></script>{{end}}<button class="btn btn-primary w-100" type="submit">Sign in</button></form><p class="mt-4 mb-0 text-center"><a href="/password-reset">Forgot your password?</a></p></div></div></div></div>{{end}}`,
	"password_reset":       `{{define "content"}}<div class="col-md-6 mx-auto"><h1>Reset password</h1>{{if .Requested}}<div class="alert alert-info">If the account is verified, we sent a six-digit code to its email address. It expires in 10 minutes.</div>{{end}}<form method="post" action="/password-reset/request" class="mb-4"><label class="form-label w-100">Account email<input class="form-control" type="email" name="email" value="{{.Email}}" required maxlength="254"></label>{{if .CaptchaKey}}<div class="g-recaptcha my-3" data-sitekey="{{.CaptchaKey}}"></div><script src="https://www.google.com/recaptcha/api.js" async defer></script>{{end}}<button class="btn btn-outline-primary">Send reset code</button></form><form method="post" action="/password-reset"><label class="form-label w-100">Account email<input class="form-control" type="email" name="email" value="{{.Email}}" required></label><label class="form-label w-100">Six-digit code<input class="form-control" name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></label><label class="form-label w-100">New password (12–72 characters)<input class="form-control" type="password" name="new_password" minlength="12" maxlength="72" required></label><button class="btn btn-primary">Reset password</button></form></div>{{end}}`,
	"admin_password_reset": `{{define "content"}}<div class="col-md-7"><h1>Password reset</h1><p>Copy this temporary password for the user. It is shown only once. Their browser sessions were revoked; their enrolled MFA is still required.</p><div class="alert alert-warning text-break"><code>{{.Temporary}}</code></div><a class="btn btn-primary" href="/profiles/{{.TargetID}}">View user profile</a></div>{{end}}`,
	"mfa":                  `{{define "content"}}<div class="col-md-6 mx-auto">{{if .Enroll}}<h1>Secure your account</h1><p>Add a passkey or authenticator app in Settings. You will be reminded on each sign-in until you enroll.</p><form method="post" action="/mfa/remind"><input type="hidden" name="csrf" value="{{.CSRF}}"><label class="form-check-label"><input class="form-check-input" type="checkbox" name="remind" value="1"> Don't remind me for 30 days</label><div><button class="btn btn-primary mt-3">Continue</button></div></form>{{else}}<h1>Second factor</h1>{{if .TOTP}}<form method="post" action="/mfa/totp"><input type="hidden" name="csrf" value="{{.CSRF}}"><label class="form-label">Authenticator code<input class="form-control" name="code" inputmode="numeric" pattern="[0-9]{6}" required></label><div><button class="btn btn-primary mt-2">Verify code</button></div></form>{{end}}{{if .Passkeys}}<button class="btn btn-outline-primary mt-3" id="passkey-login">Use passkey</button>{{end}}{{end}}<div id="passkey-error" class="text-danger mt-2"></div></div>` + passkeyScript + `{{end}}`,
	"dashboard":            `{{define "content"}}<h1>Dashboard</h1><p>{{.Count}} connection records visible to you.</p><p>The directory and connection records are planning data. Transport and live status will be connected after the protocol is defined.</p>{{end}}`,
	"settings":             `{{define "content"}}<h1>Account security</h1><section class="card mb-3"><div class="card-body"><h2 class="h5">Password</h2><form method="post" action="/settings/password"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Current password<input class="form-control" type="password" name="current_password" required></label> <label>New password (12–72 characters)<input class="form-control" type="password" name="new_password" minlength="12" maxlength="72" required></label><div><button class="btn btn-outline-primary mt-2">Change password</button></div></form></div></section><section class="card mb-3"><div class="card-body"><h2 class="h5">Authenticator app</h2>{{if .TOTP}}<p>Enabled</p><form method="post" action="/settings/totp/remove"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Current code<input class="form-control" name="code" required></label><button class="btn btn-outline-danger mt-2">Remove TOTP</button></form>{{else}}<form method="post" action="/settings/totp/begin"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="btn btn-outline-primary">Set up TOTP</button></form>{{end}}</div></section><section class="card"><div class="card-body"><h2 class="h5">Passkeys</h2><button class="btn btn-outline-primary mb-3" id="passkey-register">Add passkey</button>{{range .Keys}}<form method="post" action="/settings/passkey/remove" class="mb-2"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.}}"><code>{{.}}</code> <button class="btn btn-outline-danger btn-sm">Remove</button></form>{{else}}<p>No passkeys enrolled.</p>{{end}}<div id="passkey-error" class="text-danger"></div></div></section><section class="card border-danger mt-3"><div class="card-body"><h2 class="h5 text-danger">Delete account</h2><p class="mb-2">Permanently remove this account and its clients.</p><a class="btn btn-outline-danger" href="/settings/delete">Delete my account</a></div></section>` + passkeyScript + `{{end}}`,
	"totp":                 `{{define "content"}}<div class="col-md-7"><h1>Set up authenticator app</h1><p>Add this secret to your authenticator app, then confirm with a current code. Keep the secret private.</p><p><code>{{.Secret}}</code></p><p class="small text-muted text-break">{{.URL}}</p><form method="post" action="/settings/totp/finish"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Six-digit code<input class="form-control" name="code" inputmode="numeric" pattern="[0-9]{6}" required></label><button class="btn btn-primary mt-2">Enable TOTP</button></form></div>{{end}}`,
	"clients":              `{{define "content"}}<h1>API clients</h1><form method="post" action="/clients" class="row g-2 mb-4"><input type="hidden" name="csrf" value="{{.CSRF}}"><div class="col-auto"><input class="form-control" name="name" placeholder="Client name" maxlength="80" required></div><div class="col-auto"><button class="btn btn-primary">Create client</button></div></form><table class="table table-striped"><thead><tr><th>Name</th><th>Created</th><th>Status</th><th></th></tr></thead><tbody>{{range .Items}}<tr><td>{{.Name}}</td><td>{{.CreatedAt}}</td><td>{{if .RevokedAt}}Revoked{{else}}Active{{end}}</td><td>{{if not .RevokedAt}}<form method="post" action="/clients/revoke"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><button class="btn btn-outline-danger btn-sm">Revoke</button></form>{{end}}</td></tr>{{end}}</tbody></table><p class="text-muted">Clients can read <code>/api/v1/directory</code> and <code>/api/v1/connections</code> with a Bearer token.</p>{{end}}`,
	"client_created":       `{{define "content"}}<h1>Client created</h1><p>Copy this token for {{.Name}}. It will not be shown again.</p><div class="alert alert-warning text-break"><code>{{.Secret}}</code></div><a href="/clients" class="btn btn-primary">Done</a>{{end}}`,
	"directory":            `{{define "content"}}<h1>Global directory</h1><p class="text-muted">Planning records only; no live DLC reachability is advertised yet.</p>{{if eq .User.Role "admin"}}<form method="post" action="/admin/directory" class="row g-2 mb-4"><input type="hidden" name="csrf" value="{{.CSRF}}"><div class="col"><input class="form-control" name="site" placeholder="Site" maxlength="64" required></div><div class="col"><input class="form-control" name="mac" placeholder="MAC" maxlength="32" required></div><div class="col"><input class="form-control" name="sap" placeholder="SAP" maxlength="8" required></div><div class="col"><input class="form-control" name="description" placeholder="Description" maxlength="250"></div><div class="col-auto"><button class="btn btn-primary">Add</button></div></form>{{end}}<table class="table table-striped"><thead><tr><th>Site</th><th>MAC</th><th>SAP</th><th>Description</th><th></th></tr></thead><tbody>{{range .Items}}<tr>{{if eq $.User.Role "admin"}}<td colspan="5"><form method="post" action="/admin/directory/update" class="row g-2"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><div class="col"><input class="form-control" name="site" value="{{.Site}}" required></div><div class="col"><input class="form-control" name="mac" value="{{.MAC}}" required></div><div class="col"><input class="form-control" name="sap" value="{{.SAP}}" required></div><div class="col"><input class="form-control" name="description" value="{{.Description}}"></div><div class="col-auto"><button class="btn btn-outline-primary btn-sm">Save</button></div></form><form method="post" action="/admin/directory/delete"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><button class="btn btn-outline-danger btn-sm">Delete</button></form></td>{{else}}<td>{{.Site}}</td><td><code>{{.MAC}}</code></td><td><code>{{.SAP}}</code></td><td>{{.Description}}</td><td></td>{{end}}</tr>{{end}}</tbody></table>{{end}}`,
	"connections":          `{{define "content"}}<h1>Connections</h1><p class="text-muted">Planned connection records; live status will arrive with transport support.</p>{{if eq .User.Role "admin"}}<form method="post" action="/admin/connections" class="row g-2 mb-4"><input type="hidden" name="csrf" value="{{.CSRF}}"><div class="col"><input class="form-control" name="owner_id" placeholder="Owner ID (from Users)" required></div><div class="col"><input class="form-control" name="name" placeholder="Name" maxlength="100" required></div><div class="col"><input class="form-control" name="remote_site" placeholder="Remote site" maxlength="64" required></div><div class="col"><input class="form-control" name="notes" placeholder="Notes" maxlength="500"></div><div class="col-auto"><button class="btn btn-primary">Add</button></div></form>{{end}}<table class="table table-striped"><thead><tr><th>Name</th><th>Owner</th><th>Remote site</th><th>Status</th><th>Notes</th><th></th></tr></thead><tbody>{{range .Items}}<tr>{{if eq $.User.Role "admin"}}<td colspan="6"><form method="post" action="/admin/connections/update" class="row g-2"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><div class="col"><input class="form-control" name="name" value="{{.Name}}" required></div><div class="col"><input class="form-control" name="owner_id" value="{{.OwnerID}}" required></div><div class="col"><input class="form-control" name="remote_site" value="{{.RemoteSite}}" required></div><div class="col">{{.Status}}</div><div class="col"><input class="form-control" name="notes" value="{{.Notes}}"></div><div class="col-auto"><button class="btn btn-outline-primary btn-sm">Save</button></div></form><form method="post" action="/admin/connections/delete"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><button class="btn btn-outline-danger btn-sm">Delete</button></form></td>{{else}}<td>{{.Name}}</td><td>{{.OwnerEmail}}</td><td>{{.RemoteSite}}</td><td>{{.Status}}</td><td>{{.Notes}}</td><td></td>{{end}}</tr>{{end}}</tbody></table>{{end}}`,
	"users":                `{{define "content"}}<div class="d-flex flex-wrap align-items-center justify-content-between gap-3 mb-3"><h1 class="mb-0">Users</h1><form method="get" action="/admin/users" class="d-flex gap-2"><input class="form-control" type="search" name="q" value="{{.Search}}" placeholder="Search email or username" aria-label="Search users"><button class="btn btn-outline-primary">Search</button></form></div><div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th>Email</th><th>Username</th><th>Verified</th><th>Role</th><th>Actions</th></tr></thead><tbody>{{range .Items}}<tr><td><a href="/profiles/{{.ID}}">{{.Email}}</a></td><td>{{.Username}}</td><td>{{if .VerifiedAt}}Yes{{else}}No{{end}}</td><td><form method="post" action="/admin/users/role" class="d-flex gap-2"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><select class="form-select form-select-sm" name="role"><option value="user" {{if eq .Role "user"}}selected{{end}}>User</option><option value="admin" {{if eq .Role "admin"}}selected{{end}}>Admin</option></select><button class="btn btn-outline-primary btn-sm">Save</button></form></td><td><div class="d-flex gap-2"><form method="post" action="/admin/users/reset-password"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><button class="btn btn-outline-secondary btn-sm">Reset password</button></form><a class="btn btn-outline-danger btn-sm" href="/admin/users/{{.ID}}/delete">Delete</a></div></td></tr>{{else}}<tr><td colspan="5">No matching users.</td></tr>{{end}}</tbody></table></div><nav aria-label="User pages"><div class="d-flex align-items-center gap-3">{{if .HasPrev}}<a class="btn btn-outline-primary btn-sm" href="/admin/users?q={{urlquery .Search}}&page={{.PrevPage}}">Previous</a>{{end}}<span>Page {{.Page}}</span>{{if .HasNext}}<a class="btn btn-outline-primary btn-sm" href="/admin/users?q={{urlquery .Search}}&page={{.NextPage}}">Next</a>{{end}}</div></nav>{{end}}`,
}

const passkeyScript = `<script src="/assets/passkeys.js" defer></script>`
